CREATE TABLE readings (
    id BIGINT NOT NULL,
    taken_on DATE NOT NULL,
    value INTEGER,
    PRIMARY KEY (id, taken_on)
) PARTITION BY RANGE (taken_on);
CREATE TABLE readings_2026 PARTITION OF readings (value WITH OPTIONS NOT NULL) FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
CREATE TABLE readings_2027 PARTITION OF readings FOR VALUES FROM ('2027-01-01') TO ('2028-01-01') PARTITION BY RANGE (id);
CREATE TABLE readings_2027_low PARTITION OF readings_2027 FOR VALUES FROM (0) TO (1000);
CREATE TABLE readings_2028 (LIKE readings INCLUDING ALL);
ALTER TABLE readings ATTACH PARTITION readings_2028 FOR VALUES FROM ('2028-01-01') TO ('2029-01-01');
CREATE TABLE readings_2025 PARTITION OF readings FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');
ALTER TABLE readings DETACH PARTITION readings_2025;
ALTER TABLE readings ADD COLUMN note TEXT;

CREATE SEQUENCE reading_numbers START 100;

CREATE FUNCTION touch() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RETURN NEW; END$$;
CREATE OR REPLACE TRIGGER readings_touch BEFORE INSERT ON readings_2026 FOR EACH ROW EXECUTE FUNCTION touch();
CREATE OR REPLACE TRIGGER readings_touch BEFORE UPDATE ON readings_2026 FOR EACH ROW EXECUTE FUNCTION touch();
CREATE CONSTRAINT TRIGGER readings_check AFTER INSERT ON readings_2026 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION touch();
